      || this.scholarTurnRun.bookId !== book.id
      || this.scholarTurnRun.instanceId !== book.instanceId
      || this.scholarTurnRun.title !== title
    ) {
      this.scholarTurnRun?.releaseInput();
      this.scholarTurnRun = {
        bookId: book.id,
        instanceId: book.instanceId,
        title,
